// vCard read in full (RFC 6350 and the RFCs that extend it). test/oracle/vcard.json
// is generated by tools/oracle/vcard.py from those RFCs and IANA's vCard Elements
// registry: the standard's whole inventory, and every example line the RFCs give (plus one
// derived from the RFC's own example for a registry value it shows nowhere).
// The page's reader (site/read/vcard.mjs, with its generated table) must read
// each line exactly as the reference reader does, and every registry entry
// must be implemented and exercised, or be listed in the shrinking debt of
// app/specs/oracle/vcard.json with a reason.
// usage: node --test test/oracle/vcard.test.mjs
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";
import { readCard, readLine } from "../../site/read/vcard.mjs";
import { PROPERTIES, PARAMETERS } from "../../site/read/vcard.table.mjs";

const { inventory, examples } = JSON.parse(readFileSync("test/oracle/vcard.json", "utf8"));
const spec = JSON.parse(readFileSync("app/specs/oracle/vcard.json", "utf8"));
const { corpus } = JSON.parse(readFileSync("test/oracle/corpus.json", "utf8"));

test("the table and the examples are what the pinned RFC and registry give", () => {
  const run = spawnSync("python3", ["-I", "tools/oracle/vcard.py", "--check", "--cache", join(tmpdir(), "prism-oracle")], { encoding: "utf8" });
  assert.equal(run.status, 0, run.stderr || run.stdout);
});

// The lines a reader reads otherwise than the reference reader, and the registry entries
// a table and its examples leave unmet beyond the debt.
const wrongLines = (read) => examples.filter((e) => JSON.stringify(read(e.raw)) !== JSON.stringify(e.expect)).map((e) => ({ id: e.id, got: read(e.raw) }));
const debt = new Set(spec.debt.map((d) => d.name));
function unmet(entries, properties, parameters) {
  const owed = entries.filter((e) => !debt.has(`${e.kind} ${e.name}`));
  return owed.filter((e) => !(e.implemented && e.examples.length)).map((e) => `${e.kind} ${e.name}`)
    .concat(owed.filter((e) => e.kind === "property" && !properties[e.name]).map((e) => `${e.name} is not in the page's table`))
    .concat(owed.filter((e) => e.kind === "parameter" && !parameters[e.name]).map((e) => `${e.name} is not in the page's table`));
}

test("every example line reads as RFC 6350 and the RFCs extending it read it", () => {
  assert.deepEqual(wrongLines(readLine), []);
});

test("every vCard registry entry is implemented and exercised, or in debt with a reason", () => {
  assert.deepEqual(unmet(inventory, PROPERTIES, PARAMETERS), []);
  assert.ok(inventory.filter((e) => e.kind === "property").length >= 35, "RFC 6350 defines at least 35 properties");
  for (const d of spec.debt) assert.ok(String(d.why ?? "").trim(), `debt ${d.name} gives no reason`);
});

test("the gates refuse a planted blind reader and a planted dropped property", () => {
  // A reader that keeps every value as written (no escapes, no components) reads lines wrong.
  assert.ok(wrongLines((raw) => ({ ...readLine(raw), value: raw.slice(raw.indexOf(":") + 1) })).length > 0);
  // A table without BDAY, and an entry no example exercises, are refused.
  const { BDAY, ...dropped } = PROPERTIES;
  assert.ok(BDAY && unmet(inventory, dropped, PARAMETERS).includes("BDAY is not in the page's table"));
  const bare = inventory.map((e) => (e.kind === "property" && e.name === "NICKNAME" ? { ...e, examples: [] } : e));
  assert.ok(unmet(bare, PROPERTIES, PARAMETERS).includes("property NICKNAME"));
});

test("every whole vCard the RFC gives is read property by property", () => {
  const cards = corpus.filter((c) => c.source === "rfc6350");
  assert.ok(cards.length);
  for (const c of cards) {
    const card = readCard(c.raw);
    if (c.expect.title) assert.equal(card.FN?.[0]?.value, c.expect.title, c.id);
    assert.ok(!card.BEGIN && !card.END && !card.VERSION, c.id);
  }
});
